"use client"

import * as React from "react"
import { useAnimate, useReducedMotion } from "motion/react"
import { Check, Loader2, LockKeyhole, TimerOff } from "lucide-react"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { useControllableState } from "@/hooks/use-controllable-state"
import { GlyphField } from "@/components/ui/glyph-field/glyph-field"
import { Greeting } from "@/components/ui/greeting/greeting"
import {
  GridContainer,
  GridCrosshair,
  GridSection,
} from "@/components/ui/grid-layout/grid-layout"
import { DEFAULT_LABELS, formatLabel } from "./config"
import { Auth07Clock, Auth07PasswordField, Auth07PinField } from "./form-parts"
import type { Auth07Method, Auth07Props } from "./types"
import { useUnlockAttempts } from "./use-auth-form"

const ALL_METHODS: Auth07Method[] = ["password", "pin"]

/** 锁屏与重新验证：已登录用户用密码或 PIN 解锁，连续失败会暂时锁定。真实认证由回调接入。 */
function Auth07({
  user,
  onUnlock,
  onSuccess,
  onSwitchAccount,
  onSignOut,
  reason = "locked",
  methods: methodsProp = ALL_METHODS,
  method: methodProp,
  defaultMethod,
  onMethodChange,
  pinLength = 6,
  maxAttempts = 5,
  lockSeconds = 30,
  timeZone,
  locale = "zh-CN",
  labels: labelsProp,
  className,
  ...props
}: Auth07Props) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp }
  // 去掉未知值和重复项，保留调用方给的顺序：第一项就是默认方式
  const validMethods = methodsProp.filter(
    (item, index) =>
      ALL_METHODS.includes(item) && methodsProp.indexOf(item) === index,
  )
  const methods = validMethods.length ? validMethods : ALL_METHODS
  const [methodState, setMethod] = useControllableState<Auth07Method>({
    prop: methodProp,
    defaultProp: defaultMethod ?? methods[0]!,
    onChange: onMethodChange,
  })
  // 受控值不在可用列表里时退回第一项，避免显示一个不能用的输入
  const method = methods.includes(methodState) ? methodState : methods[0]!
  const length = Math.max(4, Math.min(8, Math.floor(pinLength) || 6))
  const attempts = useUnlockAttempts({
    maxAttempts: Math.max(1, Math.floor(maxAttempts) || 5),
    lockSeconds: Math.max(1, Math.floor(lockSeconds) || 30),
  })
  const [password, setPassword] = React.useState("")
  const [pin, setPin] = React.useState("")
  const [capsLock, setCapsLock] = React.useState(false)
  const [unlocked, setUnlocked] = React.useState(false)
  const [failCount, setFailCount] = React.useState(0)
  const passwordRef = React.useRef<HTMLInputElement>(null)
  const pinRef = React.useRef<HTMLInputElement>(null)
  const successRef = React.useRef<HTMLHeadingElement>(null)
  const [fieldScope, animate] = useAnimate<HTMLDivElement>()
  const reduced = useReducedMotion()
  const id = React.useId()
  const messageId = `${id}-message`
  const disabled = attempts.pending || attempts.locked

  // 打开、切换方式、失败重试与锁定结束后，焦点都回到当前方式的输入
  React.useEffect(() => {
    if (unlocked || attempts.locked) return
    ;(method === "pin" ? pinRef : passwordRef).current?.focus()
  }, [method, failCount, attempts.locked, unlocked])
  React.useEffect(() => {
    if (unlocked) successRef.current?.focus()
  }, [unlocked])
  React.useEffect(() => {
    if (!failCount || reduced || !fieldScope.current) return
    void animate(
      fieldScope.current,
      { x: [0, -8, 8, -5, 5, -2, 0] },
      { duration: 0.32, ease: "easeOut" },
    )
  }, [failCount, reduced, animate, fieldScope])

  async function submit(currentMethod: Auth07Method, secret: string) {
    if (disabled || unlocked) return
    if (currentMethod === "pin" ? secret.length !== length : !secret) {
      ;(currentMethod === "pin" ? pinRef : passwordRef).current?.focus()
      return
    }
    const ok = await attempts.run(() =>
      onUnlock({ method: currentMethod, secret }),
    )
    setPassword("")
    setPin("")
    if (ok) {
      setUnlocked(true)
      onSuccess?.({ method: currentMethod })
    } else {
      setFailCount((count) => count + 1)
    }
  }

  function switchMethod(next: Auth07Method) {
    setMethod(next)
    attempts.clearFailure()
    setCapsLock(false)
  }

  const failure = attempts.failure
  const errorText =
    failure && !attempts.locked
      ? formatLabel(labels.attempts, {
          message:
            failure.message ||
            (method === "pin" ? labels.wrongPin : labels.wrongPassword),
          count: failure.remaining,
        })
      : ""
  const state = unlocked
    ? "unlocked"
    : attempts.locked
      ? "locked"
      : attempts.pending
        ? "pending"
        : errorText
          ? "error"
          : "idle"
  const otherMethod = methods.find((item) => item !== method)
  const ReasonIcon = reason === "expired" ? TimerOff : LockKeyhole

  return (
    <div
      data-slot="auth-07"
      data-method={method}
      data-state={state}
      data-reason={reason}
      className={cn(
        "relative isolate flex min-h-svh w-full flex-col overflow-hidden bg-background text-foreground",
        className,
      )}
      {...props}
    >
      {/* 背景字符场：中间留白，只在四周低对比度地流动 */}
      <GlyphField
        aria-hidden="true"
        glyphs="hex"
        fade="center"
        density={0.5}
        fontSize={13}
        speed={0.015}
        className="absolute inset-0 min-h-0 opacity-50"
      />
      <GridContainer className="relative flex max-w-sm flex-1 flex-col justify-center py-12">
        <GridSection
          topLine
          crosshair
          data-slot="auth-07-panel"
          className="bg-background"
        >
          {/* 上沿是本行自己画的 screen-line-top，十字要比默认位置下移 1px 才压在线上 */}
          <GridCrosshair position="top-left" className="-top-[5px]" />
          <GridCrosshair position="top-right" className="-top-[5px]" />
          <div className="px-4 pt-10 pb-8 sm:px-6">
            <Auth07Clock
              timeZone={timeZone}
              locale={locale}
              label={labels.clock}
            />
          </div>
          <div className="flex flex-col items-center gap-3 border-t border-dashed border-edge px-4 pt-7 text-center sm:px-6">
            <Avatar data-slot="auth-07-avatar" className="size-14">
              {user.avatar ? <AvatarImage src={user.avatar} alt="" /> : null}
              <AvatarFallback className="text-lg font-medium text-foreground">
                {Array.from(user.name.trim())[0] ?? ""}
              </AvatarFallback>
            </Avatar>
            <div className="flex flex-col items-center gap-1">
              <h1 className="text-lg font-medium tracking-tight">
                <Greeting name={user.name} suffix="" />
              </h1>
              {/* 解锁后原因已不成立，只留问候 */}
              {unlocked ? null : (
                <p
                  data-slot="auth-07-reason"
                  className="flex items-center gap-1.5 text-sm text-muted-foreground"
                >
                  <ReasonIcon aria-hidden="true" className="size-3.5" />
                  {reason === "expired" ? labels.expired : labels.locked}
                </p>
              )}
            </div>
          </div>
          <div className="px-4 pt-6 pb-7 sm:px-6">
            {unlocked ? (
              <div
                data-slot="auth-07-success"
                className="flex flex-col items-center gap-2 py-2 text-center"
              >
                <span className="flex size-10 items-center justify-center rounded-full border border-edge bg-primary/10 text-primary">
                  <Check aria-hidden="true" className="size-5" />
                </span>
                <h2
                  ref={successRef}
                  tabIndex={-1}
                  className="font-medium outline-none"
                >
                  {labels.unlocked}
                </h2>
                <p role="status" className="text-sm text-muted-foreground">
                  {formatLabel(labels.unlockedDescription, { name: user.name })}
                </p>
              </div>
            ) : (
              <form
                noValidate
                aria-label={labels.form}
                data-slot="auth-07-form"
                onSubmit={(event) => {
                  event.preventDefault()
                  void submit(method, method === "pin" ? pin : password)
                }}
                className="flex flex-col gap-2"
              >
                {/* 给密码管理器识别账号用，不显示 */}
                {method === "password" ? (
                  <input
                    type="text"
                    name="username"
                    autoComplete="username"
                    value={user.email ?? user.name}
                    readOnly
                    hidden
                  />
                ) : null}
                <div ref={fieldScope} data-slot="auth-07-field">
                  {method === "pin" ? (
                    <Auth07PinField
                      inputRef={pinRef}
                      length={length}
                      value={pin}
                      onChange={(value) => {
                        setPin(value)
                        attempts.clearFailure()
                      }}
                      onComplete={(value) => void submit("pin", value)}
                      label={formatLabel(labels.pin, { length })}
                      invalid={!!errorText}
                      describedBy={messageId}
                      disabled={disabled}
                    />
                  ) : (
                    <Auth07PasswordField
                      inputRef={passwordRef}
                      label={labels.password}
                      value={password}
                      onValueChange={(value) => {
                        setPassword(value)
                        attempts.clearFailure()
                      }}
                      onCapsLockChange={setCapsLock}
                      showLabel={labels.showPassword}
                      hideLabel={labels.hidePassword}
                      invalid={!!errorText}
                      describedBy={messageId}
                      disabled={disabled}
                    />
                  )}
                </div>
                {/* 预留一行，错误、倒计时、大写锁定提示出现时按钮不跳动 */}
                <div
                  data-slot="auth-07-message"
                  className="flex min-h-5 flex-col gap-1 text-xs leading-5"
                >
                  {attempts.locked ? (
                    <>
                      {/* 倒计时只给眼睛看；读屏在锁定开始时播报一次 */}
                      <p
                        id={messageId}
                        data-slot="auth-07-lockout"
                        className="text-destructive tabular-nums"
                      >
                        {formatLabel(labels.lockedOut, {
                          seconds: attempts.remaining,
                        })}
                      </p>
                      <p role="alert" className="sr-only">
                        {formatLabel(labels.lockedOut, {
                          seconds: attempts.lockTotal,
                        })}
                      </p>
                    </>
                  ) : errorText ? (
                    <p
                      id={messageId}
                      role="alert"
                      data-slot="auth-07-error"
                      className="text-destructive"
                    >
                      {errorText}
                    </p>
                  ) : null}
                  {method === "password" && capsLock && !attempts.locked ? (
                    <p
                      role="status"
                      data-slot="auth-07-caps-lock"
                      className="text-muted-foreground"
                    >
                      {labels.capsLock}
                    </p>
                  ) : null}
                </div>
                <Button
                  type="submit"
                  size="lg"
                  className="w-full"
                  disabled={disabled}
                >
                  {attempts.pending ? (
                    <>
                      <Loader2 aria-hidden="true" className="animate-spin" />
                      {labels.unlocking}
                    </>
                  ) : (
                    labels.unlock
                  )}
                </Button>
                {otherMethod ? (
                  <Button
                    type="button"
                    variant="link"
                    size="lg"
                    data-slot="auth-07-switch-method"
                    disabled={attempts.pending}
                    className="self-center text-muted-foreground hover:text-foreground"
                    onClick={() => switchMethod(otherMethod)}
                  >
                    {otherMethod === "pin" ? labels.usePin : labels.usePassword}
                  </Button>
                ) : null}
              </form>
            )}
          </div>
        </GridSection>
        {(onSwitchAccount || onSignOut) && !unlocked ? (
          <div
            data-slot="auth-07-footer"
            className="flex items-center justify-center gap-2 pt-4 text-sm"
          >
            {onSwitchAccount ? (
              <Button
                type="button"
                variant="link"
                size="lg"
                className="text-muted-foreground hover:text-foreground"
                onClick={onSwitchAccount}
              >
                {labels.switchAccount}
              </Button>
            ) : null}
            {onSwitchAccount && onSignOut ? (
              <span
                aria-hidden="true"
                className="size-1 rounded-full bg-edge"
              />
            ) : null}
            {onSignOut ? (
              <Button
                type="button"
                variant="link"
                size="lg"
                className="text-muted-foreground hover:text-foreground"
                onClick={onSignOut}
              >
                {labels.signOut}
              </Button>
            ) : null}
          </div>
        ) : null}
      </GridContainer>
    </div>
  )
}

export { Auth07 }
export type {
  Auth07Method,
  Auth07Props,
  Auth07Reason,
  Auth07User,
} from "./types"
export type { Auth07Labels } from "./config"

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

"use client"

import * as React from "react"

// 全页面共用一个对齐整秒的定时器：多个时钟同时挂载也只有一个 setTimeout 在跑，
// 并且所有实例的秒数在同一帧跳动。
const listeners = new Set<() => void>()
let timer: number | undefined

function schedule() {
  timer = window.setTimeout(
    () => {
      listeners.forEach((listener) => listener())
      if (listeners.size) schedule()
    },
    1005 - (Date.now() % 1000),
  ) // 多等 5ms，避免定时器提前触发时读到上一秒
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  if (listeners.size === 1) schedule()
  return () => {
    listeners.delete(listener)
    if (!listeners.size) window.clearTimeout(timer)
  }
}

/**
 * 当前时间的毫秒时间戳，按 `step` 对齐（默认每秒）。
 * 服务端渲染与水合期间返回 `null`，水合完成后才给出真实时间，
 * 静态导出的 HTML 因此永远不会带着过期的时间。
 *
 * @param step 对齐粒度（毫秒）；快照不变时组件不会重新渲染，所以只显示分钟的组件传 `60_000` 即可
 */
function useNow(step = 1000): number | null {
  return React.useSyncExternalStore(
    subscribe,
    () => Math.floor(Date.now() / step) * step,
    () => null,
  )
}

export { useNow }

"use client"

import * as React from "react"
import { Button } from "@/components/ui/button"
import { Auth07 } from "@/components/auth-07/auth-07"

/** 演示后端仅用于体验界面，接入时替换为真实的会话验证接口。 */
export default function LockScreenPage() {
  // 换一个 key 就是重新锁定：组件回到初始状态
  const [session, setSession] = React.useState(0)
  const [unlocked, setUnlocked] = React.useState(false)
  const [notice, setNotice] = React.useState("")
  return (
    <main data-slot="auth-07-demo" className="relative bg-background">
      <div className="absolute inset-x-0 top-0 z-20 flex items-center justify-between gap-3 px-4 pt-3 text-xs text-muted-foreground">
        <p>演示密码 yiui2026 · PIN 123456</p>
        {unlocked ? (
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setUnlocked(false)
              setNotice("")
              setSession((value) => value + 1)
            }}
          >
            重新锁定
          </Button>
        ) : null}
      </div>
      <Auth07
        key={session}
        user={{ name: "林薇", email: "linwei@example.com" }}
        maxAttempts={3}
        lockSeconds={5}
        onUnlock={async ({ method, secret }) => {
          await new Promise((resolve) => setTimeout(resolve, 350))
          if (method === "password" && secret !== "yiui2026")
            throw new Error("密码错误")
          if (method === "pin" && secret !== "123456")
            throw new Error("PIN 错误")
        }}
        onSuccess={() => setUnlocked(true)}
        onSwitchAccount={() => setNotice("接入后在这里打开账号选择页")}
        onSignOut={() => setNotice("接入后在这里清除会话并返回登录页")}
      />
      <p
        role="status"
        className="absolute inset-x-0 bottom-3 z-20 px-4 text-center text-xs text-muted-foreground"
      >
        {notice}
      </p>
    </main>
  )
}

import type * as React from "react"
import type { Auth07Labels } from "./config"

type Auth07Method = "password" | "pin"
type Auth07Reason = "locked" | "expired"
type Auth07User = {
  /** 显示在问候语里；没有头像时取第一个字作为占位 */
  name: string
  email?: string
  /** 头像地址 */
  avatar?: string
}

type Auth07Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 当前登录的用户。 */
  user: Auth07User
  /**
   * 验证密码或 PIN，失败时抛出 Error；错误对象带数字属性 `retryAfter`（秒）时立即锁定这么久。
   */
  onUnlock: (values: { method: Auth07Method; secret: string }) => Promise<void>
  /** 验证成功后的通知。 */
  onSuccess?: (values: { method: Auth07Method }) => void
  /** 切换账号；未传时不显示入口。 */
  onSwitchAccount?: () => void
  /** 退出登录；未传时不显示入口。 */
  onSignOut?: () => void
  /** 锁屏原因：手动锁定或会话过期。@default "locked" */
  reason?: Auth07Reason
  /** 可用的验证方式，只有一种时不显示切换链接。@default ["password", "pin"] */
  methods?: Auth07Method[]
  /** 受控的验证方式。 */
  method?: Auth07Method
  /** 初始验证方式；默认取 `methods` 的第一项。 */
  defaultMethod?: Auth07Method
  /** 验证方式变化通知。 */
  onMethodChange?: (method: Auth07Method) => void
  /** PIN 位数，范围 4–8。@default 6 */
  pinLength?: number
  /** 连续失败多少次后锁定。@default 5 */
  maxAttempts?: number
  /** 锁定秒数。@default 30 */
  lockSeconds?: number
  /** 时钟使用的 IANA 时区；未传时在挂载后取浏览器时区。 */
  timeZone?: string
  /** 时间与日期的区域格式。@default "zh-CN" */
  locale?: string
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth07Labels>
}

export type { Auth07Method, Auth07Props, Auth07Reason, Auth07User }

const DEFAULT_LABELS = {
  /** 根节点的读屏名称 */
  region: "锁屏",
  /** 时钟区的读屏名称 */
  clock: "当前时间",
  /** reason="locked" 时的原因说明 */
  locked: "屏幕已锁定",
  /** reason="expired" 时的原因说明 */
  expired: "登录已过期，请重新验证身份",
  /** 验证表单的读屏名称 */
  form: "验证身份",
  password: "密码",
  /** PIN 输入的读屏名称；{length} 为位数 */
  pin: "PIN 码，共 {length} 位",
  showPassword: "显示密码",
  hidePassword: "隐藏密码",
  capsLock: "大写锁定已开启",
  unlock: "解锁",
  unlocking: "验证中…",
  usePin: "改用 PIN",
  usePassword: "改用密码",
  switchAccount: "切换账号",
  signOut: "退出登录",
  /** 回调抛出的错误没有 message 时使用 */
  wrongPassword: "密码错误",
  wrongPin: "PIN 错误",
  /** 验证失败后的提示；{message} 为回调抛出的原因，{count} 为剩余次数 */
  attempts: "{message}，还可以尝试 {count} 次",
  /** 锁定期间的倒计时；{seconds} 为剩余秒数 */
  lockedOut: "尝试次数过多，请 {seconds} 秒后再试",
  unlocked: "已解锁",
  /** 解锁后的说明；{name} 为用户名 */
  unlockedDescription: "欢迎回来，{name}",
}
type Auth07Labels = typeof DEFAULT_LABELS
function formatLabel(
  template: string,
  values: Record<string, string | number>,
) {
  return template.replace(/\{(\w+)\}/g, (_, key: string) =>
    String(values[key] ?? ""),
  )
}
export { DEFAULT_LABELS, formatLabel }
export type { Auth07Labels }

"use client"

import * as React from "react"

type UnlockFailure = {
  /** 回调抛出的原因，没有时为空字符串 */
  message: string
  /** 本次失败后还能再试几次；进入锁定时为 0 */
  remaining: number
}

/** 错误对象上的 `retryAfter`（秒），只接受有限正数。 */
function readRetryAfter(caught: unknown) {
  if (typeof caught !== "object" || caught === null) return 0
  const value = (caught as { retryAfter?: unknown }).retryAfter
  return typeof value === "number" && Number.isFinite(value) && value > 0
    ? Math.ceil(value)
    : 0
}

/**
 * 解锁请求：同步锁拦截回车与 PIN 自动提交的重复请求，累计失败次数，
 * 达到上限或服务端给出 `retryAfter` 时锁定一段时间，到时自动恢复并清零。
 */
function useUnlockAttempts({
  maxAttempts,
  lockSeconds,
}: {
  maxAttempts: number
  lockSeconds: number
}) {
  const lock = React.useRef(false)
  const failures = React.useRef(0)
  const [pending, setPending] = React.useState(false)
  const [failure, setFailure] = React.useState<UnlockFailure | null>(null)
  const [deadline, setDeadline] = React.useState(0)
  const [remaining, setRemaining] = React.useState(0)
  // 进入锁定时的总秒数：读屏只在锁定开始时播报一次，不跟着倒计时逐秒念
  const [lockTotal, setLockTotal] = React.useState(0)

  React.useEffect(() => {
    if (!deadline) return
    const tick = () => {
      const left = Math.max(0, Math.ceil((deadline - Date.now()) / 1000))
      setRemaining(left)
      if (left === 0) {
        failures.current = 0
        setDeadline(0)
        setLockTotal(0)
        setFailure(null)
      }
    }
    tick()
    const timer = window.setInterval(tick, 250)
    return () => window.clearInterval(timer)
  }, [deadline])

  function startLock(seconds: number) {
    setRemaining(seconds)
    setLockTotal(seconds)
    // 只在失败回调里读取时间，不参与服务端渲染
    setDeadline(Date.now() + seconds * 1000)
  }

  const locked = deadline > 0

  async function run(action: () => Promise<void>) {
    if (lock.current || locked) return false
    lock.current = true
    setPending(true)
    setFailure(null)
    try {
      await action()
      failures.current = 0
      return true
    } catch (caught) {
      const retryAfter = readRetryAfter(caught)
      failures.current += 1
      const left = Math.max(0, maxAttempts - failures.current)
      setFailure({
        message: caught instanceof Error ? caught.message : "",
        remaining: retryAfter ? 0 : left,
      })
      if (retryAfter) startLock(retryAfter)
      else if (left === 0) startLock(lockSeconds)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }

  return {
    pending,
    failure,
    clearFailure: () => setFailure(null),
    locked,
    remaining,
    lockTotal,
    run,
  }
}

export { readRetryAfter, useUnlockAttempts }
export type { UnlockFailure }

"use client"

import * as React from "react"
import { OTPInputContext } from "input-otp"
import { Eye, EyeOff } from "lucide-react"
import { Button } from "@/components/ui/button"
import { InputOTP, InputOTPGroup } from "@/components/ui/input-otp"
import { cn } from "@/lib/utils"
import { useNow } from "@/hooks/use-now"
import { BarField } from "@/components/ui/bar-field/bar-field"
import { LocalTime } from "@/components/ui/local-time/local-time"

function subscribeNothing() {
  return () => {}
}

/** 浏览器时区；服务端与水合期间为 null，挂载后才读取，首屏 HTML 因此不带任何时区信息。 */
function useBrowserTimeZone() {
  return React.useSyncExternalStore(
    subscribeNothing,
    () => Intl.DateTimeFormat().resolvedOptions().timeZone,
    () => null,
  )
}

const dateFormatters = new Map<string, Intl.DateTimeFormat>()
function formatDate(now: number, locale: string, timeZone: string) {
  const key = `${locale}|${timeZone}`
  let formatter = dateFormatters.get(key)
  if (!formatter) {
    formatter = new Intl.DateTimeFormat(locale, {
      timeZone,
      month: "long",
      day: "numeric",
      weekday: "long",
    })
    dateFormatters.set(key, formatter)
  }
  return formatter.format(now)
}

/** 大号时:分与日期星期；挂载前用同尺寸的占位，不读取当前时间。 */
function Auth07Clock({
  timeZone: timeZoneProp,
  locale,
  label,
}: {
  timeZone?: string
  locale: string
  label: string
}) {
  const browserZone = useBrowserTimeZone()
  const timeZone = timeZoneProp ?? browserZone
  const now = useNow(60_000)
  const date = now !== null && timeZone ? formatDate(now, locale, timeZone) : ""
  return (
    <div
      data-slot="auth-07-clock"
      data-ready={date ? "" : undefined}
      role="group"
      aria-label={label}
      className="flex flex-col items-center gap-1.5"
    >
      <p className="text-5xl leading-none font-light tracking-tight tabular-nums sm:text-7xl">
        {timeZone ? (
          <LocalTime
            timeZone={timeZone}
            locale={locale}
            showSeconds={false}
            showDifference={false}
          />
        ) : (
          <span
            data-slot="auth-07-clock-placeholder"
            aria-hidden="true"
            className="text-muted-foreground"
          >
            --:--
          </span>
        )}
      </p>
      {/* 日期行固定一行高度，挂载前后不跳动 */}
      <p className="h-5 text-sm text-muted-foreground">{date}</p>
    </div>
  )
}

/** 方条密码框：显示/隐藏切换，按键时检测大写锁定。 */
function Auth07PasswordField({
  inputRef,
  label,
  value,
  onValueChange,
  onCapsLockChange,
  showLabel,
  hideLabel,
  invalid,
  describedBy,
  disabled,
}: {
  inputRef: React.Ref<HTMLInputElement>
  label: string
  value: string
  onValueChange: (value: string) => void
  onCapsLockChange: (on: boolean) => void
  showLabel: string
  hideLabel: string
  invalid: boolean
  describedBy?: string
  disabled: boolean
}) {
  const [visible, setVisible] = React.useState(false)
  const detect = (event: React.KeyboardEvent<HTMLInputElement>) => {
    // 合成事件（自动填充等）没有修饰键状态，跳过
    if (typeof event.getModifierState === "function")
      onCapsLockChange(event.getModifierState("CapsLock"))
  }
  return (
    <BarField
      inputRef={inputRef}
      name="password"
      type={visible ? "text" : "password"}
      autoComplete="current-password"
      label={label}
      size="lg"
      value={value}
      onValueChange={onValueChange}
      onKeyDown={detect}
      onKeyUp={detect}
      onBlur={() => onCapsLockChange(false)}
      aria-invalid={invalid || undefined}
      aria-describedby={describedBy}
      disabled={disabled}
      suffix={
        <Button
          type="button"
          variant="ghost"
          size="icon-lg"
          disabled={disabled}
          onClick={() => setVisible((current) => !current)}
          aria-label={visible ? hideLabel : showLabel}
          aria-pressed={visible}
          className="shrink-0 text-muted-foreground hover:text-foreground"
        >
          {visible ? <EyeOff aria-hidden="true" /> : <Eye aria-hidden="true" />}
        </Button>
      }
    />
  )
}

/** PIN 的一格：只显示圆点，不显示数字。 */
function Auth07PinSlot({
  index,
  invalid,
}: {
  index: number
  invalid: boolean
}) {
  const context = React.useContext(OTPInputContext)
  const slot = context?.slots[index]
  return (
    <div
      data-slot="auth-07-pin-slot"
      data-active={slot?.isActive || undefined}
      data-filled={slot?.char ? "" : undefined}
      aria-invalid={invalid || undefined}
      className={cn(
        "relative flex h-9 min-w-0 flex-1 items-center justify-center border-y border-r border-edge bg-muted/60 transition-colors first:rounded-l-md first:border-l last:rounded-r-md pointer-coarse:h-11",
        "data-active:z-10 data-active:border-foreground/25 data-active:bg-background",
        "aria-invalid:border-destructive",
      )}
    >
      {slot?.char ? (
        <span
          aria-hidden="true"
          className="size-2.5 rounded-full bg-foreground"
        />
      ) : null}
      {slot?.hasFakeCaret ? (
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 flex items-center justify-center"
        >
          <span className="h-4 w-px animate-caret-blink bg-foreground duration-1000" />
        </span>
      ) : null}
    </div>
  )
}

/** 数字 PIN：输满自动提交，格子里只显示圆点。 */
function Auth07PinField({
  inputRef,
  length,
  value,
  onChange,
  onComplete,
  label,
  invalid,
  describedBy,
  disabled,
}: {
  inputRef: React.Ref<HTMLInputElement>
  length: number
  value: string
  onChange: (value: string) => void
  onComplete: (value: string) => void
  label: string
  invalid: boolean
  describedBy?: string
  disabled: boolean
}) {
  return (
    <div data-slot="auth-07-pin">
      <InputOTP
        ref={inputRef}
        maxLength={length}
        value={value}
        onChange={onChange}
        onComplete={onComplete}
        pattern="^[0-9]*$"
        inputMode="numeric"
        autoComplete="off"
        aria-label={label}
        aria-invalid={invalid || undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        containerClassName="w-full"
      >
        <InputOTPGroup className="w-full rounded-md">
          {Array.from({ length }, (_, index) => (
            <Auth07PinSlot key={index} index={index} invalid={invalid} />
          ))}
        </InputOTPGroup>
      </InputOTP>
    </div>
  )
}

